insert into lp_conteudos (landing_page_id, elemento, conteudo, versao)
select a.id, t.elemento, t.conteudo, t.versao
from tmp_controle_lps t
join (
  select distinct on (n) id, n
  from (select id, public.norm_nome(nome) as n from landing_pages) x
  order by n, id
) a on a.n = public.norm_nome(t.lp)
where not exists (
  select 1 from lp_conteudos c
  where c.landing_page_id = a.id
    and c.elemento = t.elemento
    and c.versao = t.versao
);

do $$
declare faltando text;
begin
  select string_agg(distinct t.lp, ', ' order by t.lp) into faltando
  from tmp_controle_lps t
  where not exists (
    select 1 from landing_pages l
    where public.norm_nome(l.nome) = public.norm_nome(t.lp)
  );
  raise notice 'LPs da planilha sem correspondência em Landing Pages: %',
    coalesce(faltando, '(nenhuma)');
end $$;

drop table if exists tmp_controle_lps;
